#include <stdio.h>
void dutchFlag(int arr[], int n) {
    int lo=0, mid=0, hi=n-1, tmp;
    while (mid<=hi) {
        if (arr[mid]==0) {
            tmp=arr[lo];
            arr[lo]=arr[mid];
            arr[mid]=tmp;
            lo++;
            mid++;
        } else if (arr[mid]==1)mid++;
        else {
            tmp=arr[mid];
            arr[mid]=arr[hi];
            arr[hi]=tmp;
            hi--;
        }
    }
}
