using namespace std;
void dutchFlag(vector<int>& a) {
    int lo=0, mid=0, hi=a.size()-1;
    while (mid<=hi) {
        if (a[mid]==0) {
            swap(a[lo++], a[mid++]);
        }else if (a[mid]==1)mid++;
        else swap(a[mid], a[hi--]);
    }
}
int main() {
    vector<int> a= {2, 0, 2, 1, 1, 0};
    dutchFlag(a);
    for (int v:a)cout<<v<<" ";
